/**
 * Pronunciation-coach (Parlometron) chrome localization.
 *
 * The UI text is localized into the user's NATIVE language — `stackConfig.languages[0]`
 * (the host passes the stack at mount; languages[0] is native, [1..] are learning).
 * `t(key, lang)` tries the FULL code first (so script variants like zh-Hant / pa-Arab
 * win), then the collapsed base (ko-polite→ko, pt-BR→pt), then English per-key — so a
 * missing/partial locale never shows a blank.
 *
 * The English block below is the source of truth. The rest are hand-authored UI
 * microcopy. `tools/gen_i18n.py` can regenerate the base locales from English via the
 * OpenAI API, but it writes BASE codes only — re-running it would drop the explicit
 * script-variant overrides (zh-Hant, pa-Arab) below, so re-add them after a regen.
 *
 * Scope: the mic-control labels around the hold-to-speak interaction. The rest of the
 * pack chrome (model setup, errors) is still hardcoded English — a larger follow-up.
 */

export type I18nKey =
  // ── Mic control (practice) ──
  | "holdToSpeak"
  | "loadingModel"
  | "listeningReleaseToStop"
  | "scoring"
  | "bootLoading"
  | "swipeHint"
  // ── Practice results / feedback chips ──
  | "resultTryAgain"
  | "resultCouldntHear"
  | "resultPerfect"
  | "resultNailedIt"
  | "resultGreat"
  | "resultPrettyGood"
  | "resultCloseKeepGoing"
  | "resultKeepPracticing"
  | "heardYouSay"
  | "couldntMakeOutWords"
  | "chipSoundedFaint"
  | "chipSoundedGarbled"
  | "chipCouldntMakeOut"
  | "chipWordsDidntMatch"
  | "chipDifferentScript"
  | "hintMoveCloser"
  // ── Practice errors / empty states ──
  | "noLanguageSelected"
  | "chooseLanguageToStudy"
  | "noPhrasesAvailable"
  | "errLoadPhrase"
  | "errStartRecording"
  | "errScoringFailed"
  | "errNetworkBlip"
  // ── Shared aria / common ──
  | "ariaClose"
  | "ariaSpeakWord"
  | "ariaPlayHeard"
  | "commonBack"
  | "commonQuit"
  | "commonDone"
  // ── Mode picker ──
  | "pickerClose"
  | "pickerTagline"
  | "pickerPractice"
  | "pickerPracticeDesc"
  | "pickerFriends"
  | "pickerFriendsDesc"
  | "pickerFooter"
  // ── Lobby ──
  | "lobbyBack"
  | "lobbyNewGame"
  | "lobbyPlayers"
  | "lobbyAddPlayer"
  | "lobbyFirstToWin"
  | "lobbyRoundsSuffix"
  | "lobbyStart"
  | "lobbyPlayerName"
  | "lobbyRemovePlayer"
  // ── Round ──
  | "roundNoStt"
  | "roundQuitGame"
  | "roundPass"
  | "roundPassTo"
  | "roundReady"
  | "roundEyebrow"
  | "roundTurn"
  | "roundTurnIndicator"
  | "roundMicGetReady"
  | "roundMicTapToStop"
  | "roundMicTryAgain"
  | "roundMicTapOrPass"
  | "roundMicTapToSpeak"
  | "roundResultGood"
  | "roundResultOkay"
  | "errNoLanguageStack"
  | "errNoTranslation"
  | "errCantLoadPhrase"
  | "errModelNotPrepared"
  | "errCouldntScore"
  // ── Results (between rounds + game over) ──
  | "resBetweenNoWinner"
  | "resWinsRound"
  | "resTieRound"
  | "resBetweenEyebrow"
  | "resPhrase"
  | "resColPlayer"
  | "resColBest"
  | "resColHeard"
  | "resColWins"
  | "resNextRound"
  | "resGameOver"
  | "resWinsGame"
  | "resTieGame"
  | "resGameOverEyebrow"
  | "resColRank"
  | "resColRoundWins"
  | "resColAvg"
  | "resPlayAgain"
  // ── Confirm / quit ──
  | "confirmDefault"
  | "cancelDefault"
  | "quitConfirmTitle"
  | "quitConfirmMsg"
  | "quitConfirmKeep"

type Dict = Record<I18nKey, string>

